"""Install manager-only permanent analyst memory and scoped read/search tools."""
import argparse,base64,fcntl,hashlib,json,os,subprocess,sys,tempfile,time,zlib
from pathlib import Path
PAYLOAD=''
BEFORE={'manager_memory_retrieval.py': '2dc37331689d38c227d3381614cf756931949c3018c700fa5837a02b2acc2f5a', 'manager_practice_bridge.py': '7c94c0c53826c720f0229d3ab8872f815812187ee88e2f6a084d898f786bc425', 'manager_remembered_runtime.py': 'a0c1553def91a241c495d500a8e0b69d9384dfc8d8c562eacd73c9518f8ab95c'}
def sha(b):return hashlib.sha256(b).hexdigest()
def atomic(path,raw):
 fd,name=tempfile.mkstemp(dir=path.parent,prefix='.library-install-')
 try:
  with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
  os.replace(name,path)
 finally:
  if os.path.exists(name):os.unlink(name)
def install(root,apply):
 state=root/'dj-manager-memory/runtime';active=json.loads((state/'ACTIVATED.json').read_text())
 code=Path(active['code']).resolve();code.relative_to((root/'dj-manager-memory/runtime-code').resolve())
 status=subprocess.check_output(['systemctl','show','dj-remembered-manager.service','-p','ActiveState','--value'],text=True).strip()
 if status not in ('failed','inactive'):raise ValueError('관리자 작업 실행 중. 변경 없음')
 public=subprocess.check_output(['systemctl','show','dj-remembered-products.timer','-p','ActiveState','--value'],text=True).strip()
 if public=='active' and not (root/'dj-public-products/runtime/PAUSED.json').exists():raise ValueError('공개픽 영향 확인 필요. 변경 없음')
 with (state/'worker.lock').open('a') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
  files={k:v.encode() for k,v in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items()};old={}
  for name,raw in files.items():
   target=code/name
   if target.is_symlink():raise ValueError('링크 경로 변경 차단')
   old[name]=target.read_bytes() if target.exists() else None
   if old[name] is not None and old[name]!=raw and (name not in BEFORE or sha(old[name])!=BEFORE[name]):raise ValueError('예상과 다른 소스: '+name)
   if name.endswith('.py'):compile(raw,str(target),'exec')
  marker=state/'PAUSED.json';pause_raw=marker.read_bytes() if marker.exists() else None
  if pause_raw is not None and json.loads(pause_raw).get('reason')!='기억과 한 경기의 원자료가 전송 한도를 넘음. 원문 유지 후 중단':raise ValueError('다른 중단 사유. 재개하지 않음')
  cli=root/'.local/bin/codex'
  for args in (['--version'],['mcp','--help']):
   result=subprocess.run([str(cli)]+args,capture_output=True,text=True,timeout=20)
   if result.returncode:raise ValueError('서버 Codex 기억 도구 지원 확인 필요. AI 요청 없음')
  print('소스·CLI 기본 검사 PASS · 설치 AI 요청 0회 · 실제 AI 도구 연결은 실행 후 확인 필요',flush=True)
  if not apply:return
  audit=state/'deployments'/('memory-library-v10-'+str(time.time_ns()));audit.mkdir(parents=True)
  for name,raw in old.items():
   if raw is not None:(audit/name).write_bytes(raw)
  (audit/'installation.json').write_text(json.dumps({'new_files':[n for n,b in old.items() if b is None],'hashes':{n:sha(b) for n,b in files.items()},'pause_preserved':pause_raw is not None},indent=2))
  changed=[]
  try:
   for name,raw in files.items():
    if (code/name).exists() and (code/name).read_bytes()!=old[name]:raise ValueError('검증 중 코드 변경')
    atomic(code/name,raw);changed.append(name)
   sys.path.insert(0,str(code));import manager_remembered_runtime as rt
   release=Path(active.get('release',root/'dj-manager-memory/releases/20261004_203930'))
   from manager_memory_library import store,stable_ref,Reader
   from manager_memory_access import NOTE
   cycles=[p for p in sorted((state/'cycles').glob('*/inputs.json')) if not all((p.parent/e/'completed.json').exists() for e in rt.ENGINES)]
   if not cycles:raise ValueError('미완료 주기 없음. 기억은 보존되며 실행 상태 확인 필요')
   pool=rt.read(cycles[0])['inputs']['pool'];report={}
   for e in rt.ENGINES:
    memory=rt.append_live_memory(rt.load_memory(release,e,pool),state,e,pool)
    memory=rt.prepare_packet({'analyst':e,'questions':pool,'memory':memory})['memory']
    ref=stable_ref(store(state,e,memory));reader=Reader(ref);reader.catalog();reader.c.close()
    packets=rt.split_packets({'analyst':e,'mode':'candidates','memory':ref,'review_scope':'all_provided_questions'},'questions',pool)
    report[e]={'memory_counts':ref['counts'],'memory_generation':ref['generation'],'input_batches':len(packets),'max_request_chars':max((len(rt.request_wire_text(p)) for p in packets),default=0)}
    # Real STDIO handshake and read (no model) using the deployed tool.
    reference=audit/(e+'.reference.json');reference.write_text(json.dumps(ref));reader=Reader(ref);rows=reader.search(limit=1)['records'];reader.c.close()
    messages=[{'jsonrpc':'2.0','id':0,'method':'initialize','params':{'protocolVersion':'2024-11-05'}},{'jsonrpc':'2.0','id':1,'method':'tools/list'}]
    if rows:messages.append({'jsonrpc':'2.0','id':2,'method':'tools/call','params':{'name':'memory_read','arguments':{'record_id':rows[0]['record_id']}}})
    proc=subprocess.run([sys.executable,str(code/'manager_memory_tools.py'),'--reference',str(reference),'--audit',str(audit/(e+'.probe.jsonl'))],input='\n'.join(map(json.dumps,messages))+'\n',capture_output=True,text=True,timeout=30)
    replies=[json.loads(l) for l in proc.stdout.splitlines()]
    if proc.returncode or len(replies)!=len(messages) or any(r.get('error') or r.get('result',{}).get('isError') for r in replies):raise ValueError('기억 도구 원문 읽기 검사 실패: '+e)
   (audit/'verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps({'check':'PASS','AI_requests':0,'analysts':report},ensure_ascii=False,indent=2),flush=True)
  except BaseException:
   for name in reversed(changed):
    if old[name] is not None:atomic(code/name,old[name])
    else:
     # Preserve newly created code rather than deleting it during rollback.
     (code/name).rename(audit/('not-activated-'+name))
   print('검증 실패. 기존 실행 코드 복원 · 원자료·추가 기억 색인 보존 · AI 재개 없음',flush=True)
   raise
  print('MEMORY_LIBRARY_INSTALLED · 백업: '+str(audit))
  interrupted=[]
  for p in state.rglob('*.pending.json'):
   if '/deployments/' in p.as_posix():continue
   prefix=str(p)[:-len('.pending.json')]
   if not any(Path(prefix+s).is_file() for s in ('.answer.json','.json')):interrupted.append(str(p.relative_to(state)))
  if interrupted:
   print(json.dumps({'unfinished_requests_preserved':interrupted,'resume':False},ensure_ascii=False,indent=2));raise SystemExit('미완료 요청이 있어 자동 재요청하지 않음. 설치 완료·일시중지 유지. 결과를 확인하세요.')
  if (marker.read_bytes() if marker.exists() else None)!=pause_raw:raise ValueError('중단 상태 변경. 재개 없음')
  if pause_raw is not None:marker.rename(audit/'PAUSED.resolved.json')
  print('MANAGER_RESUME_READY · 기억 저장·조회 준비 완료 · 실전 AI 도구 사용은 이후 로그로 확인')
def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path('/home/ubuntu'));p.add_argument('--apply',action='store_true');a=p.parse_args();os.umask(0o077);install(a.root.resolve(),a.apply)
if __name__=='__main__':main()
